try:
    import re
    b = config.get('body')
    if isinstance(b, dict):
        f = str(b.get('field') or '')
        a = str(b.get('answer') or '').strip()
        if f == 'phone_last4':
            digits = re.sub(r'[^0-9]', '', a)
            if len(digits) >= 4:
                b['answer'] = digits[-4:]
        elif f == 'date_of_birth':
            m = re.match(r'^(\d{1,2})[./ -](\d{1,2})[./ -](\d{4})$', a)
            if m:
                b['answer'] = m.group(3) + '-' + m.group(2).zfill(2) + '-' + m.group(1).zfill(2)
except Exception:
    pass

